def imgteam(name): return f'<img class="crest" src="{logos[name]}" alt="{name}队徽">'
def profile(): return f'<img class="avatar" src="{avatar}" alt="徐sir的足球主题头像"><div class="grow"><h1>徐sir</h1><div class="support">{imgteam("阿森纳")}<span>主队 · 阿森纳</span></div></div>'
def progress(): return '<div class="progress" role="progressbar" aria-label="下一解锁进度" aria-valuemin="0" aria-valuemax="100" aria-valuenow="90"><span></span></div><div class="row between progress-meta"><span>还差 <b class="num">120</b> 分 · 球场名片</span><span class="num">90%</span></div>'
def heading(title): return f'<div class="section-heading"><h2>{title}</h2><button class="link">查看全部预测</button></div>'
def unlock(compact=False): return f'<section class="tray unlock space {"compact-unlock" if compact else ""}" aria-label="解锁预览"><div class="unlock-art"><img src="{avatar}" alt="青绿头像框预览"></div><div class="grow"><div class="unlock-title">已解锁 · 青绿头像框</div><small>下一解锁 · 球场名片</small></div><button class="link" aria-label="查看全部解锁">查看全部</button></section>'
rows=[('阿森纳','切尔西','2:1','2:1','精确命中','+12','hit12'),('利物浦','热刺','1:0','2:0','胜平负命中','+3','hit3'),('曼城','纽卡斯尔','2:0','1:1','未命中','0','miss')]
def result_cards():
    return ''.join(f'<article class="card match-card"><div class="row between"><small>模拟比赛 · 已结束</small><span class="chip {cl}">{res}</span></div><div class="faceoff"><div class="team">{imgteam(a)}{a}</div><div class="score"><strong class="num">{actual}</strong><small>实际比分</small></div><div class="team away">{imgteam(b)}{b}</div></div><div class="result-line"><span class="muted">我的预测 <b class="num">{pred}</b></span><span>预测分 <b class="points num">{pts}</b></span></div></article>' for a,b,pred,actual,res,pts,cl in rows)
def mini_results():
    return '<section class="card">'+''.join(f'<article class="mini-result"><div class="row between"><div class="row"><div class="badge-pair">{imgteam(a)}{imgteam(b)}</div><h3>{a} · {b}</h3></div><b class="points num">{pts}<small> 分</small></b></div><div class="row between"><div class="mini-scores"><span>预测 <b class="num">{pred}</b></span><span>实际 <b class="num">{actual}</b></span></div><span class="chip {cl}">{res}</span></div></article>' for a,b,pred,actual,res,pts,cl in rows)+'<small class="tiny">模拟比赛 · 右侧为预测分</small></section>'
def band(level,acc,count): return f'<div class="data-band"><div><strong class="num">Lv.{level}</strong><small>等级</small></div><div><strong class="num">{acc}%</strong><small>胜平负准确率</small></div><div><strong class="num">{count}</strong><small>有效预测场次</small></div></div>'

